function annotationGeometry(mode,coords){if(mode==="point"&&coords.length)return turf.point(coords[0]).geometry;if(["area","volume"].includes(mode)&&coords.length>2)return turf.polygon([[...coords,coords[0]]]).geometry;if(mode==="stats"&&coords.length>1){const a=coords[0],b=coords.at(-1);return turf.polygon([[[a[0],a[1]],[b[0],a[1]],[b[0],b[1]],[a[0],b[1]],[a[0],a[1]]]]).geometry}if(coords.length>1)return turf.lineString(coords).geometry;return null}
