function renderAnnotationManager(){const box=$("#db-annotations-list");if(!box)return;if(!savedAnnotations.length){box.innerHTML='<div class="db-ann-empty">No hay mediciones guardadas todavía.</div>';return}box.innerHTML=savedAnnotations.map(a=>'<article class="db-ann-row" data-ann="'+esc(a.id)+'"><button class="db-ann-focus" title="Acercar">⌖</button><div><strong>'+esc(a.title||a.annotation_type)+'</strong><small>'+esc(a.annotation_type)+' · '+esc(a.visibility)+'</small></div>'+(currentSession?'<button class="db-ann-edit" title="Editar">✎</button><button class="db-ann-delete" title="Eliminar">⌫</button>':'')+'</article>').join("");box.querySelectorAll(".db-ann-focus").forEach(b=>b.onclick=()=>focusAnnotation(b.closest("[data-ann]").dataset.ann));box.querySelectorAll(".db-ann-edit").forEach(b=>b.onclick=()=>editAnnotation(b.closest("[data-ann]").dataset.ann));box.querySelectorAll(".db-ann-delete").forEach(b=>b.onclick=()=>deleteAnnotation(b.closest("[data-ann]").dataset.ann))}
function focusAnnotation(id){const a=savedAnnotations.find(x=>x.id===id);if(!a?.geometry)return;try{const bb=turf.bbox({type:"Feature",geometry:a.geometry,properties:{}});if(bb.every(Number.isFinite)){if(bb[0]===bb[2]&&bb[1]===bb[3])projectMap.flyTo({center:[bb[0],bb[1]],zoom:19});else projectMap.fitBounds([[bb[0],bb[1]],[bb[2],bb[3]]],{padding:90,maxZoom:20})}}catch(e){console.warn(e)}}
