function isFolder(e){return e.type===TYPES.DIRECTORY||e.type===TYPES.DRONEDB}function name(e){return e.name||String(e.path||"").split("/").pop()}function thumb(e){return base+"/thumb?path="+encodeURIComponent(e.path)+"&size=320"}
