function addFootprints(){const features=allEntries.filter(e=>e.type!==TYPES.GEORASTER&&e.type!==TYPES.VECTOR&&geometryOf(e)).map(e=>({type:"Feature",geometry:geometryOf(e),properties:{path:e.path,type:e.type,name:name(e),hash:e.hash||"",thumb:e.type===TYPES.GEOIMAGE?thumb(e):"",inline:e.type===TYPES.GEOIMAGE?inlineUrl(e.path):""}}));if(!features.length)return;projectMap.addSource("ddb-footprints",{type:"geojson",data:{type:"FeatureCollection",features}});projectMap.addLayer({id:"ddb-footprints-fill",type:"fill",source:"ddb-footprints",filter:["==",["geometry-type"],"Polygon"],paint:{"fill-color":"#18b8d1","fill-opacity":.12}});projectMap.addLayer({id:"ddb-footprints-line",type:"line",source:"ddb-footprints",paint:{"line-color":"#19c4dc","line-width":2}});projectMap.addLayer({id:"ddb-footprints-point",type:"circle",source:"ddb-footprints",filter:["==",["geometry-type"],"Point"],paint:{"circle-radius":6,"circle-color":["case",["==",["get","type"],TYPES.GEOIMAGE],"#a8d64b","#18b8d1"],"circle-stroke-color":"#fff","circle-stroke-width":2}});for(const id of["ddb-footprints-fill","ddb-footprints-line","ddb-footprints-point"])projectMap.on("click",id,e=>{const p=e.features?.[0]?.properties;if(!p)return;const entry=allEntries.find(x=>x.path===p.path),url=entry&&productUrl(entry);let html='<strong>'+esc(p.name)+'</strong><br><small>'+esc(TYPE_NAMES[p.type]||"Producto geoespacial")+'</small>';if(Number(p.type)===TYPES.GEOIMAGE)html='<a class="db-photo-popup" href="'+esc(p.inline)+'" target="_blank" rel="noopener"><img src="'+esc(p.thumb)+'" alt=""><strong>'+esc(p.name)+'</strong></a><small>'+e.lngLat.lat.toFixed(6)+', '+e.lngLat.lng.toFixed(6)+'</small>';else if(url)html+='<br><a href="'+url+'">Abrir producto</a>';new maplibregl.Popup({maxWidth:"320px"}).setLngLat(e.lngLat).setHTML(html).addTo(projectMap)})}
