function startTool(mode,button){if(mode==="clear"){drawCoords=[];drawMode=null;ensureDrawSource();projectMap.getSource("iv-draw").setData({type:"FeatureCollection",features:[]});$("#db-analysis").classList.add("hidden");return}if(mode==="contours"){generateContours();return}drawMode=mode;drawCoords=[];document.querySelectorAll("[data-gis]").forEach(b=>b.classList.remove("active"));button.classList.add("active");toast(mode==="inspect"?"Toca el mapa para consultar":mode==="point"?"Toca el mapa para marcar":mode==="stats"?"Marca dos esquinas del área a analizar":"Toca para añadir vértices · doble toque/clic para finalizar")}
