async function renderTree(){if(!allEntries.length)await collectAll();const rows=[...allEntries].sort((a,b)=>String(a.path).localeCompare(String(b.path),undefined,{numeric:true,sensitivity:"base"}));let html='<div class="db-tree-row '+(!currentPath?"active":"")+'" data-tree="" style="--depth:0"><span class="twisty">▾</span><span class="kind">●</span><span class="label">'+esc(project.dronedb.dataset)+'</span><span class="db-tree-count">'+rows.filter(e=>!isFolder(e)).length+'</span></div>';for(const e of rows){const path=String(e.path||""),parts=path.split("/").filter(Boolean),ancestors=parts.slice(0,-1).map((_,i)=>parts.slice(0,i+1).join("/"));if(ancestors.some(x=>!treeExpanded.has(x)))continue;const depth=Math.max(1,parts.length),folder=isFolder(e),expanded=treeExpanded.has(path);html+='<div class="db-tree-row '+(currentPath===path?"active":"")+'" data-tree="'+esc(path)+'" style="--depth:'+depth+'"><span class="twisty">'+(folder?(expanded?"▾":"›"):"")+'</span><span class="kind">'+iconFor(e)+'</span><span class="label">'+esc(name(e))+'</span><span class="db-tree-type">'+esc(extOf(e))+'</span></div>'}$("#db-tree").innerHTML=html;$("#db-tree").querySelectorAll("[data-tree]").forEach(r=>r.onclick=async ev=>{const path=r.dataset.tree;if(!path){currentPath="";await refresh();return}const e=allEntries.find(x=>x.path===path);if(!e)return;if(isFolder(e)){if(ev.target.classList.contains("twisty")){treeExpanded.has(path)?treeExpanded.delete(path):treeExpanded.add(path);await renderTree();return}treeExpanded.add(path);currentPath=path;await refresh()}else{selectedEntry=e;showProperties(e)}})}
function extOf(e){const n=name(e).toLowerCase(),m=n.match(/(\.tar\.gz|\.[^.]+)$/);return m?m[1].replace(".","").toUpperCase():(TYPE_NAMES[e.type]||"DATA")}
function bytesLabel(v){const n=Number(v);if(!Number.isFinite(n)||n<=0)return"—";const u=["B","KB","MB","GB","TB"],i=Math.min(u.length-1,Math.floor(Math.log(n)/Math.log(1024)));return(n/1024**i).toFixed(i?1:0)+" "+u[i]}
function setTabUI(tab){document.querySelectorAll("[data-tab]").forEach(x=>x.classList.toggle("active",x.dataset.tab===tab));$("#db-files").classList.toggle("hidden",tab!=="files");$("#db-map-tab").classList.toggle("hidden",tab!=="map");$("#db-info-tab").classList.toggle("hidden",tab!=="info")}
function showProperties(e){if(!e)return;selectedEntry=e;const panel=$("#db-properties"),g=geometryOf(e),url=productUrl(e);$("#db-prop-title").textContent=name(e);$("#db-prop-preview").innerHTML=e.type===TYPES.GEORASTER?'<img src="'+esc(thumb(e))+'" alt="">':'<div class="db-prop-icon">'+iconFor(e)+'</div>';const rows=[["Tipo",TYPE_NAMES[e.type]||e.type],["Formato",extOf(e)],["Ruta",e.path],["Tamaño",bytesLabel(e.size)],["Hash",e.hash||"—"],["Georreferenciado",g?"Sí":"No"],["Sistema CRS",e.crs||e.epsg||"Según metadatos"]];$("#db-prop-body").innerHTML=rows.map(([a,b])=>'<div class="db-prop-row"><span>'+esc(a)+'</span><strong>'+esc(b)+'</strong></div>').join("");$("#db-prop-open").disabled=!url;$("#db-prop-open").onclick=()=>{if(url)location.href=url};$("#db-prop-map").onclick=async()=>{setTabUI("map");await showMapTab();focusEntryOnMap(e)};panel.classList.remove("hidden")}
function focusEntryOnMap(e){if(!projectMap||!e)return;const g=geometryOf(e);if(g)try{const bb=turf.bbox({type:"Feature",geometry:g,properties:{}});if(bb.every(Number.isFinite)){if(bb[0]===bb[2]&&bb[1]===bb[3])projectMap.flyTo({center:[bb[0],bb[1]],zoom:19});else projectMap.fitBounds([[bb[0],bb[1]],[bb[2],bb[3]]],{padding:90,maxZoom:20})}}catch(err){console.warn(err)}const ri=mapRasters.findIndex(x=>x.path===e.path);if(ri>=0){setRasterVisibility("ddb-ortho-"+ri,true);analysisRaster=e}}
function kmlCoordinates(text){return String(text||"").trim().split(/\s+/).map(x=>x.split(",").slice(0,3).map(Number)).filter(x=>x.length>=2&&Number.isFinite(x[0])&&Number.isFinite(x[1]))}
function kmlToGeoJSON(text){const doc=new DOMParser().parseFromString(text,"application/xml");if(doc.querySelector("parsererror"))throw Error("KML no válido");const features=[];doc.querySelectorAll("Placemark").forEach((p,i)=>{const properties={name:p.querySelector("name")?.textContent?.trim()||"Elemento "+(i+1),description:p.querySelector("description")?.textContent?.trim()||""};let geometry=null;const point=p.querySelector("Point coordinates"),line=p.querySelector("LineString coordinates"),poly=p.querySelector("Polygon outerBoundaryIs LinearRing coordinates");if(point){const c=kmlCoordinates(point.textContent)[0];if(c)geometry={type:"Point",coordinates:c}}else if(line){const c=kmlCoordinates(line.textContent);if(c.length>1)geometry={type:"LineString",coordinates:c}}else if(poly){const c=kmlCoordinates(poly.textContent);if(c.length>3)geometry={type:"Polygon",coordinates:[c]}}if(geometry)features.push({type:"Feature",properties,geometry})});return{type:"FeatureCollection",features}}
async function parseLocalGIS(file){const n=file.name.toLowerCase();if(n.endsWith(".geojson")||n.endsWith(".json")){const j=JSON.parse(await file.text());return j.type==="FeatureCollection"?j:{type:"FeatureCollection",features:j.type==="Feature"?[j]:[]}}if(n.endsWith(".kml"))return kmlToGeoJSON(await file.text());if(n.endsWith(".kmz")){if(!window.JSZip)throw Error("JSZip no disponible");const zip=await JSZip.loadAsync(await file.arrayBuffer()),k=Object.values(zip.files).find(x=>/\.kml$/i.test(x.name));if(!k)throw Error("KMZ sin KML");return kmlToGeoJSON(await k.async("text"))}if(n.endsWith(".zip")){if(typeof window.shp!=="function")throw Error("Lector SHP no disponible");const out=await window.shp(await file.arrayBuffer());if(Array.isArray(out))return{type:"FeatureCollection",features:out.flatMap(x=>x.features||[])};return out}if(n.endsWith(".gpkg"))return await importGeoPackageFile(file);throw Error("Formato no compatible")}
async function addLocalLayer(file,fc){if(!fc?.features?.length)throw Error("La capa no contiene geometrías");if(!mapReady)await initProjectMap();const key="local-"+Date.now()+"-"+localLayers.length,sid=key+"-src",ids=[];projectMap.addSource(sid,{type:"geojson",data:fc});for(const [kind,filter,paint] of [["fill",["==",["geometry-type"],"Polygon"],{"fill-color":"#a8d64b","fill-opacity":.18,"fill-outline-color":"#dff38e"}],["line",["==",["geometry-type"],"LineString"],{"line-color":"#a8d64b","line-width":2.5}],["circle",["==",["geometry-type"],"Point"],{"circle-radius":6,"circle-color":"#a8d64b","circle-stroke-color":"#fff","circle-stroke-width":2}]]){const id=key+"-"+kind;projectMap.addLayer({id,type:kind,source:sid,filter,paint});ids.push(id);projectMap.on("click",id,e=>{const p=e.features?.[0]?.properties||{},rows=Object.entries(p).slice(0,12).map(([a,b])=>'<tr><th>'+esc(a)+'</th><td>'+esc(b)+'</td></tr>').join("");new maplibregl.Popup({maxWidth:"360px"}).setLngLat(e.lngLat).setHTML('<strong>'+esc(file.name)+'</strong><table class="db-vector-props">'+rows+'</table>').addTo(projectMap)})}localLayers.push({name:file.name,sourceId:sid,layerIds:ids,featureCount:fc.features.length});try{const bb=turf.bbox(fc);if(bb.every(Number.isFinite))projectMap.fitBounds([[bb[0],bb[1]],[bb[2],bb[3]]],{padding:80,maxZoom:19})}catch{}renderMapLayerList()}
async function importLocalFiles(files){if(!files?.length)return;setTabUI("map");await showMapTab();for(const file of files)try{const fc=await parseLocalGIS(file);await addLocalLayer(file,fc);toast(file.name+" · "+fc.features.length+" elementos")}catch(e){console.error(e);toast(file.name+": "+e.message)}}

function workSourceId(id){return"iv-work-"+String(id).replace(/[^a-zA-Z0-9_-]/g,"")}
function layerStyle(l){return{color:l?.style?.color||"#19a6c4",opacity:Number(l?.style?.opacity??.55)}}
function featureCollectionForLayer(id){return{type:"FeatureCollection",features:workFeatures.filter(f=>f.layer_id===id&&f.geometry).map(f=>({type:"Feature",geometry:f.geometry,properties:{...(f.properties||{}),__id:f.id,__name:f.name||""}}))}}


let geoPackageLoadPromise=null;
async function ensureGeoPackageLib(){if(window.GeoPackage?.GeoPackageAPI)return window.GeoPackage;if(geoPackageLoadPromise)return geoPackageLoadPromise;geoPackageLoadPromise=new Promise((resolve,reject)=>{const sc=document.createElement("script");sc.src="https://unpkg.com/@ngageoint/geopackage@4.2.6/dist/geopackage.min.js";sc.onload=()=>{try{window.GeoPackage.setSqljsWasmLocateFile(file=>"https://unpkg.com/@ngageoint/geopackage@4.2.6/dist/"+file);resolve(window.GeoPackage)}catch(e){reject(e)}};sc.onerror=()=>reject(Error("No fue posible cargar GeoPackage JS"));document.head.appendChild(sc)});return geoPackageLoadPromise}
function gpkgFieldName(v,used){let n=exportSafeName(v).toLowerCase().slice(0,48)||"atributo";if(["id","geometry"].includes(n))n="iv_"+n;let out=n,i=2;while(used.has(out))out=n.slice(0,44)+"_"+i++;used.add(out);return out}
function gpkgLayerData(layerId){const fc=exportFeatureCollection(layerId),used=new Set(["name","iv_id"]),keys=[...new Set(fc.features.flatMap(f=>Object.keys(f.properties||{})).filter(k=>!["name","iv_id"].includes(k)))],map=new Map(keys.map(k=>[k,gpkgFieldName(k,used)])),columns=[{name:"name",dataType:"TEXT"},{name:"iv_id",dataType:"TEXT"},...map.values()].map(name=>({name,dataType:"TEXT"}));const features=fc.features.map(f=>({type:"Feature",geometry:f.geometry,properties:{name:String(f.properties?.name??""),iv_id:String(f.properties?.iv_id??""),...Object.fromEntries([...map].map(([old,n])=>{const v=f.properties?.[old];return[n,v==null?"":typeof v==="object"?JSON.stringify(v):String(v)]}))}}));return{columns,features}}
async function buildGeoPackage(layerIds){const G=await ensureGeoPackageLib(),gp=await G.GeoPackageAPI.create();try{const usedTables=new Set();for(const layerId of layerIds){const l=workLayers.find(x=>x.id===layerId);if(!l)continue;const data=gpkgLayerData(layerId);if(!data.features.length)continue;let table=exportSafeName(l.name).toLowerCase().slice(0,45)||"layer",base=table,i=2;while(usedTables.has(table))table=base.slice(0,41)+"_"+i++;usedTables.add(table);gp.createFeatureTableWithProperties(table,data.columns);await gp.addGeoJSONFeaturesToGeoPackage(data.features,table,false)}return await gp.export()}finally{gp.close()}}
async function exportGeoPackage(layerIds,filename){try{const ids=layerIds.filter(id=>exportFeatureCollection(id).features.length);if(!ids.length)return toast("No hay entidades para exportar");toast("Generando GeoPackage…");const bytes=await buildGeoPackage(ids);downloadBlob(filename,new Blob([bytes],{type:"application/geopackage+sqlite3"}));toast("GeoPackage generado · "+ids.length+" capas")}catch(e){console.error(e);toast("No se pudo generar GPKG: "+e.message)}}
async function importGeoPackageFile(file){const G=await ensureGeoPackageLib(),gp=await G.GeoPackageAPI.open(new Uint8Array(await file.arrayBuffer()));try{const tables=gp.getFeatureTables()||[],features=[];for(const table of tables){const result=gp.queryForGeoJSONFeatures(table);for(const feature of result){feature.properties={...(feature.properties||{}),_gpkg_table:table};features.push(feature)}result.close?.()}if(!features.length)throw Error("El GeoPackage no contiene tablas vectoriales");return{type:"FeatureCollection",features}}finally{gp.close()}}
function exportSafeName(v){return String(v||"capa").normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-zA-Z0-9_-]+/g,"_").replace(/^_+|_+$/g,"").slice(0,64)||"capa"}
function exportFeatureCollection(layerId){const layer=workLayers.find(l=>l.id===layerId);return{type:"FeatureCollection",name:layer?.name||"Island View",crs:{type:"name",properties:{name:"urn:ogc:def:crs:OGC:1.3:CRS84"}},features:workFeatures.filter(f=>f.layer_id===layerId&&f.geometry).map(f=>({type:"Feature",geometry:structuredClone(f.geometry),properties:{name:f.name||"",...(f.properties||{}),iv_id:f.id}}))}}
function workKmlColor(layer){const st=layerStyle(layer),h=st.color.replace("#","").padEnd(6,"0"),r=h.slice(0,2),g=h.slice(2,4),b=h.slice(4,6),a=Math.round(Math.max(0,Math.min(1,st.opacity))*255).toString(16).padStart(2,"0");return a+b+g+r}
function workLayerKML(layerId){const layer=workLayers.find(l=>l.id===layerId),fc=exportFeatureCollection(layerId),color=workKmlColor(layer);const body=fc.features.map(f=>{const props=Object.entries(f.properties||{}).filter(([k])=>k!=="name").map(([k,v])=>"<Data name=\""+xmlEsc(k)+"\"><value>"+xmlEsc(typeof v==="object"?JSON.stringify(v):v)+"</value></Data>").join("");return"<Placemark><name>"+xmlEsc(f.properties?.name||"Entidad")+"</name><styleUrl>#ivStyle</styleUrl><ExtendedData>"+props+"</ExtendedData>"+kmlGeometry(f.geometry)+"</Placemark>"}).join("");return'<?xml version="1.0" encoding="UTF-8"?><kml xmlns="http://www.opengis.net/kml/2.2"><Document><name>'+xmlEsc(layer?.name||"Island View")+'</name><Style id="ivStyle"><IconStyle><color>'+color+'</color><scale>1.1</scale></IconStyle><LineStyle><color>'+color+'</color><width>3</width></LineStyle><PolyStyle><color>'+color+'</color></PolyStyle></Style>'+body+"</Document></kml>"}
function downloadBlob(filename,blob){const a=document.createElement("a"),url=URL.createObjectURL(blob);a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
async function shpBlobForLayer(layerId){if(!window.shpwrite?.zip)throw Error("Exportador SHP no disponible");const layer=workLayers.find(l=>l.id===layerId),safe=exportSafeName(layer?.name),fc=exportFeatureCollection(layerId);if(!fc.features.length)throw Error("La capa no tiene entidades");const out=await Promise.resolve(window.shpwrite.zip(fc,{folder:safe,filename:safe,outputType:"blob",compression:"DEFLATE",types:{point:safe+"_puntos",polygon:safe+"_poligonos",polyline:safe+"_lineas"}}));return out instanceof Blob?out:new Blob([out],{type:"application/zip"})}
async function exportWorkLayer(format,layerId=activeWorkLayerId){const layer=workLayers.find(l=>l.id===layerId);if(!layer)return toast("Selecciona una capa editable");const fc=exportFeatureCollection(layerId),safe=exportSafeName(layer.name);if(!fc.features.length)return toast("La capa no tiene entidades para exportar");try{if(format==="geojson")downloadText(safe+".geojson",JSON.stringify(fc,null,2),"application/geo+json");else if(format==="kml")downloadText(safe+".kml",workLayerKML(layerId),"application/vnd.google-earth.kml+xml");else if(format==="kmz"){const z=new JSZip();z.file("doc.kml",workLayerKML(layerId));z.file("metadata.json",JSON.stringify({project:project?.name||projectKey,layer:layer.name,crs:"EPSG:4326",exported_at:new Date().toISOString()},null,2));downloadBlob(safe+".kmz",await z.generateAsync({type:"blob",compression:"DEFLATE"}))}else if(format==="shp")downloadBlob(safe+"_SHP.zip",await shpBlobForLayer(layerId));else if(format==="gpkg"){await exportGeoPackage([layerId],safe+".gpkg");return}toast(layer.name+" exportada · "+format.toUpperCase())}catch(e){console.error(e);toast("No se pudo exportar: "+e.message)}}
async function exportWorkWorkspace(){if(!workLayers.length)return toast("No hay capas editables");const usable=workLayers.filter(l=>exportFeatureCollection(l.id).features.length);if(!usable.length)return toast("Las capas editables están vacías");const zip=new JSZip(),root=zip.folder(exportSafeName(project?.name||projectKey)+"_GIS");try{root.file(exportSafeName(project?.name||projectKey)+".gpkg",await buildGeoPackage(usable.map(l=>l.id)))}catch(e){root.file("GPKG_EXPORT_ERROR.txt",e.message)}root.file("README.txt","Island View S.A.S. · Exportación GIS\nProyecto: "+(project?.name||projectKey)+"\nCRS: WGS84 / EPSG:4326\nFecha: "+new Date().toISOString()+"\nCapas: "+usable.length+"\n");for(const l of usable){const dir=root.folder(exportSafeName(l.name)),fc=exportFeatureCollection(l.id);dir.file(exportSafeName(l.name)+".geojson",JSON.stringify(fc,null,2));dir.file(exportSafeName(l.name)+".kml",workLayerKML(l.id));try{const kmz=new JSZip();kmz.file("doc.kml",workLayerKML(l.id));dir.file(exportSafeName(l.name)+".kmz",await kmz.generateAsync({type:"blob",compression:"DEFLATE"}));dir.file(exportSafeName(l.name)+"_SHP.zip",await shpBlobForLayer(l.id))}catch(e){dir.file("SHP_EXPORT_ERROR.txt",e.message)}}const blob=await zip.generateAsync({type:"blob",compression:"DEFLATE"});downloadBlob(exportSafeName(project?.name||projectKey)+"_GIS.zip",blob);toast("Paquete GIS generado · "+usable.length+" capas")}
function ensureWorkMapLayer(l){if(!projectMap||!l)return;const sid=workSourceId(l.id),fc=featureCollectionForLayer(l.id),st=layerStyle(l);if(projectMap.getSource(sid)){projectMap.getSource(sid).setData(fc);applyWorkLayerStyle(l);return}projectMap.addSource(sid,{type:"geojson",data:fc});const defs=[["fill","Polygon",{"fill-color":st.color,"fill-opacity":st.opacity}],["line","LineString",{"line-color":st.color,"line-width":3,"line-opacity":Math.min(1,st.opacity+.25)}],["circle","Point",{"circle-radius":6,"circle-color":st.color,"circle-opacity":Math.min(1,st.opacity+.25),"circle-stroke-color":"#fff","circle-stroke-width":2}]];for(const [suffix,geom,paint] of defs){const id=sid+"-"+suffix;projectMap.addLayer({id,type:suffix,source:sid,filter:["==",["geometry-type"],geom],paint});projectMap.on("click",id,e=>{const fid=e.features?.[0]?.properties?.__id;if(fid)selectWorkFeature(fid)})}}
function applyWorkLayerStyle(l){if(!projectMap||!l)return;const sid=workSourceId(l.id),st=layerStyle(l),fill=sid+"-fill",line=sid+"-line",circle=sid+"-circle";if(projectMap.getLayer(fill)){projectMap.setPaintProperty(fill,"fill-color",st.color);projectMap.setPaintProperty(fill,"fill-opacity",st.opacity)}if(projectMap.getLayer(line)){projectMap.setPaintProperty(line,"line-color",st.color);projectMap.setPaintProperty(line,"line-opacity",Math.min(1,st.opacity+.25))}if(projectMap.getLayer(circle)){projectMap.setPaintProperty(circle,"circle-color",st.color);projectMap.setPaintProperty(circle,"circle-opacity",Math.min(1,st.opacity+.25))}}
async function loadWorkLayers(){if(!sb||!projectDbId)return;const {data:ls,error:le}=await sb.from("project_layers").select("*").eq("project_id",projectDbId).order("created_at");if(le){console.warn(le);return}workLayers=ls||[];const {data:fs,error:fe}=await sb.from("project_features").select("*").eq("project_id",projectDbId).order("created_at");if(fe){console.warn(fe);return}workFeatures=fs||[];if(!activeWorkLayerId&&workLayers.length)activeWorkLayerId=workLayers[0].id;for(const l of workLayers)ensureWorkMapLayer(l);renderWorkEditor()}
function renderWorkEditor(){const sel=$("#db-work-layer"),list=$("#db-work-layer-list");if(!sel||!list)return;sel.innerHTML=workLayers.map(l=>'<option value="'+esc(l.id)+'">'+esc(l.name)+'</option>').join("")||'<option value="">Sin capas editables</option>';if(activeWorkLayerId)sel.value=activeWorkLayerId;const active=workLayers.find(l=>l.id===activeWorkLayerId),st=layerStyle(active);$("#db-layer-color").value=st.color;$("#db-layer-opacity").value=st.opacity;list.innerHTML=workLayers.map(l=>'<div class="db-work-layer-row '+(l.id===activeWorkLayerId?"active":"")+'" style="--layer-color:'+esc(layerStyle(l).color)+'"><i></i><span><strong>'+esc(l.name)+'</strong><small>'+workFeatures.filter(f=>f.layer_id===l.id).length+' entidades · '+esc(l.visibility)+'</small></span><button data-work-focus="'+esc(l.id)+'">Usar</button></div>').join("")||'<div class="db-loading">Crea una capa para comenzar a digitalizar.</div>';list.querySelectorAll("[data-work-focus]").forEach(b=>b.onclick=()=>{activeWorkLayerId=b.dataset.workFocus;renderWorkEditor()})}
function requireEditor(){if(!sb||!currentSession){openLogin();toast("Inicia sesión con una cuenta editora");return false}if(!projectDbId){toast("Proyecto sin catálogo Supabase");return false}return true}
async function createWorkLayer(){if(!requireEditor())return;const n=prompt("Nombre de la nueva capa GIS:","Huellas de edificaciones");if(!n?.trim())return;const {data,error}=await sb.from("project_layers").insert({project_id:projectDbId,name:n.trim(),geometry_type:"mixed",visibility:"project",style:{color:"#19a6c4",opacity:.55}}).select().single();if(error)return toast(error.message.includes("row-level")?"Tu cuenta no tiene permiso de edición":error.message);workLayers.push(data);activeWorkLayerId=data.id;ensureWorkMapLayer(data);renderWorkEditor();renderMapLayerList();toast("Capa creada")}
async function deleteWorkLayer(){if(!requireEditor()||!activeWorkLayerId)return;const l=workLayers.find(x=>x.id===activeWorkLayerId);if(!l||!confirm("Eliminar la capa “"+l.name+"” y todas sus entidades?"))return;const {error}=await sb.from("project_layers").delete().eq("id",l.id);if(error)return toast(error.message.includes("row-level")?"Tu cuenta no tiene permiso de edición":error.message);const sid=workSourceId(l.id);for(const x of["fill","line","circle"])if(projectMap?.getLayer(sid+"-"+x))projectMap.removeLayer(sid+"-"+x);if(projectMap?.getSource(sid))projectMap.removeSource(sid);workFeatures=workFeatures.filter(f=>f.layer_id!==l.id);workLayers=workLayers.filter(x=>x.id!==l.id);activeWorkLayerId=workLayers[0]?.id||null;clearFeatureSelection();renderWorkEditor();renderMapLayerList();toast("Capa eliminada")}
async function saveWorkLayerStyle(){if(!requireEditor()||!activeWorkLayerId)return;const l=workLayers.find(x=>x.id===activeWorkLayerId);if(!l)return;const style={...(l.style||{}),color:$("#db-layer-color").value,opacity:Number($("#db-layer-opacity").value)};const {error}=await sb.from("project_layers").update({style,updated_at:new Date().toISOString()}).eq("id",l.id);if(error)return toast(error.message.includes("row-level")?"Tu cuenta no tiene permiso de edición":error.message);l.style=style;applyWorkLayerStyle(l);renderWorkEditor();renderMapLayerList();toast("Estilo actualizado")}
function startWorkDraw(mode,button){if(!requireEditor())return;if(!activeWorkLayerId)return toast("Crea o selecciona una capa editable");drawMode=mode;drawCoords=[];ensureDrawSource();projectMap.getSource("iv-draw").setData({type:"FeatureCollection",features:[]});document.querySelectorAll("[data-edit-draw]").forEach(b=>b.classList.remove("active"));button.classList.add("active");toast(mode==="gis-point"?"Toca el mapa para crear el punto":"Toca para añadir vértices · doble toque/clic para finalizar")}
async function saveNewWorkFeature(mode,coords){if(!requireEditor()||!activeWorkLayerId)return;let geometry;if(mode==="gis-point")geometry={type:"Point",coordinates:coords[0]};if(mode==="gis-line"&&coords.length>1)geometry={type:"LineString",coordinates:coords};if(mode==="gis-polygon"&&coords.length>2)geometry={type:"Polygon",coordinates:[[...coords,coords[0]]]};if(!geometry)return toast("Geometría incompleta");const layer=workLayers.find(l=>l.id===activeWorkLayerId),baseName=mode==="gis-point"?"Punto":mode==="gis-line"?"Línea":"Polígono";const {data,error}=await sb.from("project_features").insert({project_id:projectDbId,layer_id:activeWorkLayerId,name:baseName+" "+(workFeatures.filter(f=>f.layer_id===activeWorkLayerId).length+1),geometry,properties:{}}).select().single();if(error)return toast(error.message.includes("row-level")?"Tu cuenta no tiene permiso de edición":error.message);workFeatures.push(data);ensureWorkMapLayer(layer);renderWorkEditor();renderMapLayerList();selectWorkFeature(data.id);drawCoords=[];ensureDrawSource();projectMap.getSource("iv-draw").setData({type:"FeatureCollection",features:[]});toast("Entidad guardada")}
function vertexFeatures(f){if(!f?.geometry)return[];let coords=[];if(f.geometry.type==="Point")coords=[f.geometry.coordinates];if(f.geometry.type==="LineString")coords=f.geometry.coordinates;if(f.geometry.type==="Polygon")coords=(f.geometry.coordinates[0]||[]).slice(0,-1);return coords.map((c,i)=>({type:"Feature",geometry:{type:"Point",coordinates:c},properties:{idx:i}}))}
function ensureVertexSource(){if(!projectMap||projectMap.getSource("iv-edit-vertices"))return;projectMap.addSource("iv-edit-vertices",{type:"geojson",data:{type:"FeatureCollection",features:[]}});projectMap.addLayer({id:"iv-edit-vertices",type:"circle",source:"iv-edit-vertices",paint:{"circle-radius":8,"circle-color":"#a8d64b","circle-stroke-color":"#fff","circle-stroke-width":2}});const start=e=>{const idx=Number(e.features?.[0]?.properties?.idx);if(!Number.isFinite(idx))return;vertexDrag={idx};projectMap.dragPan.disable();e.preventDefault?.()};projectMap.on("mousedown","iv-edit-vertices",start);projectMap.on("touchstart","iv-edit-vertices",start);const move=e=>{if(vertexDrag&&selectedWorkFeatureId)moveSelectedVertex(vertexDrag.idx,[e.lngLat.lng,e.lngLat.lat])};projectMap.on("mousemove",move);projectMap.on("touchmove",move);const end=()=>{if(vertexDrag){vertexDrag=null;projectMap.dragPan.enable()}};projectMap.on("mouseup",end);projectMap.on("touchend",end)}
function selectWorkFeature(id){const f=workFeatures.find(x=>x.id===id);if(!f)return;selectedWorkFeatureId=id;ensureVertexSource();projectMap.getSource("iv-edit-vertices").setData({type:"FeatureCollection",features:vertexFeatures(f)});$("#db-feature-editor").classList.remove("hidden");$("#db-feature-name").value=f.name||"";$("#db-feature-props").value=JSON.stringify(f.properties||{},null,2);$("#db-gis-editor").classList.remove("hidden");activeWorkLayerId=f.layer_id;renderWorkEditor()}
function moveSelectedVertex(idx,coord){const f=workFeatures.find(x=>x.id===selectedWorkFeatureId);if(!f)return;if(f.geometry.type==="Point")f.geometry.coordinates=coord;if(f.geometry.type==="LineString"&&f.geometry.coordinates[idx])f.geometry.coordinates[idx]=coord;if(f.geometry.type==="Polygon"){const ring=f.geometry.coordinates[0];if(ring?.[idx]){ring[idx]=coord;if(idx===0)ring[ring.length-1]=coord}}ensureWorkMapLayer(workLayers.find(x=>x.id===f.layer_id));projectMap.getSource("iv-edit-vertices")?.setData({type:"FeatureCollection",features:vertexFeatures(f)})}
function clearFeatureSelection(){selectedWorkFeatureId=null;$("#db-feature-editor")?.classList.add("hidden");projectMap?.getSource("iv-edit-vertices")?.setData({type:"FeatureCollection",features:[]})}
async function saveSelectedFeature(){if(!requireEditor()||!selectedWorkFeatureId)return;const f=workFeatures.find(x=>x.id===selectedWorkFeatureId);if(!f)return;let properties;try{properties=JSON.parse($("#db-feature-props").value||"{}")}catch{return toast("Los atributos JSON no son válidos")}f.name=$("#db-feature-name").value.trim()||f.name;f.properties=properties;const {error}=await sb.from("project_features").update({name:f.name,properties:f.properties,geometry:f.geometry,updated_at:new Date().toISOString()}).eq("id",f.id);if(error)return toast(error.message.includes("row-level")?"Tu cuenta no tiene permiso de edición":error.message);ensureWorkMapLayer(workLayers.find(x=>x.id===f.layer_id));toast("Cambios guardados")}
async function deleteSelectedFeature(){if(!requireEditor()||!selectedWorkFeatureId)return;const f=workFeatures.find(x=>x.id===selectedWorkFeatureId);if(!f||!confirm("Eliminar esta entidad GIS?"))return;const {error}=await sb.from("project_features").delete().eq("id",f.id);if(error)return toast(error.message.includes("row-level")?"Tu cuenta no tiene permiso de edición":error.message);workFeatures=workFeatures.filter(x=>x.id!==f.id);ensureWorkMapLayer(workLayers.find(x=>x.id===f.layer_id));clearFeatureSelection();renderWorkEditor();renderMapLayerList();toast("Entidad eliminada")}
async function renderInfo(){if(!allEntries.length)await collectAll();mapRasters=allEntries.filter(e=>e.type===TYPES.GEORASTER);const files=allEntries.filter(e=>!isFolder(e)),counts={};files.forEach(e=>counts[e.type]=(counts[e.type]||0)+1);const exts=[...new Set(files.map(extOf))].sort();$("#db-info-title").textContent=project.name;$("#db-info-description").textContent=project.description||"";$("#db-info-badges").innerHTML='<span>'+files.length+' archivos</span><span>'+mapRasters.length+' raster</span><span>'+allEntries.filter(e=>geometryOf(e)).length+' georreferenciados</span>';$("#db-info-summary").innerHTML=Object.entries(counts).map(([t,n])=>'<div class="db-info-row"><span>'+esc(TYPE_NAMES[t]||"Otro")+'</span><strong>'+n+'</strong></div>').join("");$("#db-info-formats").innerHTML='<div class="db-format-cloud">'+exts.map(x=>'<span>'+esc(x)+'</span>').join("")+'</div><p>GeoTIFF/COG · LAS/LAZ/COPC · OBJ/GLB/3D Tiles · SHP/GeoJSON/KML/KMZ/GPKG y productos compatibles del Registry.</p>';$("#db-info-tools").innerHTML=["Punto / coordenadas","Distancia","Área / perímetro","Inspección raster","Perfil de elevación","Curvas de nivel","Volumen de acopios","Opacidad y orden de capas","Potree + EDL","Altura 3D","Anotaciones","Exportación GIS"].map(x=>'<span>✓ '+x+'</span>').join("");$("#db-info-source").innerHTML='<p><b>Registry:</b> '+esc(project.dronedb.registry)+'</p><p><b>Organización:</b> '+esc(project.dronedb.org)+'</p><p><b>Dataset:</b> '+esc(project.dronedb.dataset)+'</p>'}
function showEntryInfo(e){$("#db-info-title").textContent=name(e);$("#db-info-description").textContent=TYPE_NAMES[e.type]||"Producto geoespacial";$("#db-info-source").innerHTML='<p><b>Ruta:</b> '+esc(e.path)+'</p><p><b>Hash:</b> '+esc(e.hash||"—")+'</p><p><b>Tipo:</b> '+esc(TYPE_NAMES[e.type]||e.type)+'</p>'}
document.querySelectorAll("[data-tab]").forEach(b=>b.onclick=async()=>{setTabUI(b.dataset.tab);if(b.dataset.tab==="map")await showMapTab();if(b.dataset.tab==="info")await renderInfo()});
