$("#db-prop-close").onclick=()=>$("#db-properties").classList.add("hidden");$("#db-gis-editor-btn").onclick=()=>{$("#db-gis-editor").classList.toggle("hidden");renderWorkEditor()};$("#db-gis-editor-close").onclick=()=>$("#db-gis-editor").classList.add("hidden");$("#db-new-work-layer").onclick=createWorkLayer;$("#db-delete-work-layer").onclick=deleteWorkLayer;$("#db-save-layer-style").onclick=saveWorkLayerStyle;$("#db-work-layer").onchange=e=>{activeWorkLayerId=e.target.value||null;clearFeatureSelection();renderWorkEditor()};document.querySelectorAll("[data-edit-draw]").forEach(b=>b.onclick=()=>startWorkDraw(b.dataset.editDraw,b));$("#db-save-feature").onclick=saveSelectedFeature;$("#db-delete-feature").onclick=deleteSelectedFeature;document.querySelectorAll("[data-work-export]").forEach(b=>b.onclick=()=>exportWorkLayer(b.dataset.workExport));$("#db-export-gpkg-project").onclick=()=>exportGeoPackage(workLayers.map(l=>l.id),exportSafeName(project?.name||projectKey)+".gpkg");$("#db-export-workspace").onclick=exportWorkWorkspace;$("#db-import-btn").onclick=()=>$("#db-import-file").click();$("#db-import-file").onchange=e=>{importLocalFiles([...e.target.files]);e.target.value=""};
$("#db-account").onclick=openLogin;$("#db-login-close").onclick=()=>$("#db-login").classList.add("hidden");$("#db-login-form").onsubmit=signInWorkspace;
