$("#db-map-home").onclick=()=>{const ll=Array.isArray(project?.coordinates)?project.coordinates:[-81.7006,12.5847];projectMap?.flyTo({center:ll,zoom:12.2,bearing:0,pitch:0})};$("#db-map-layers-btn").onclick=()=>$("#db-map-layers").classList.toggle("hidden");$("#db-map-layers-close").onclick=()=>$("#db-map-layers").classList.add("hidden");$("#db-map-full").onclick=()=>{const el=$("#db-map-tab");document.fullscreenElement?document.exitFullscreen():el.requestFullscreen?.()};$("#db-refresh").onclick=refresh;$("#db-search").oninput=()=>renderGrid(entries);$("#db-view-toggle").onclick=()=>{view=view==="grid"?"compact":"grid";$("#db-files").style.gridTemplateColumns=view==="grid"?"":"repeat(auto-fill,minmax(210px,1fr))"};
